package com.mbox.staff
import org.json.JSONObject
import java.util.UUID
const val commercePolicyRoot="/api/staff/native-commerce-policy"
class CommercePolicyBoard(val data:JSONObject){val actor=data.getString("employeeId");val enabled=data.getInt("protocol")==1&&data.getBoolean("durableCommands");val row=data.getJSONObject("row")}
fun commercePolicyCommand(actor:StaffIdentity,b:CommercePolicyBoard,action:String,value:String,reason:String):LiveCommand{require(b.enabled&&b.actor==actor.employeeId&&actor.allows("payment.policy.manage"));require(reason.trim().length in 3..1000){"请填写3至1000字调整原因"};val r=b.row;val body=JSONObject().put("expectedVersion",r.getInt("policyVersion")).put("reason",reason.trim());val message=when(action){"online-payment"->{require(value in listOf("true","false"));val on=value=="true";require(!on||r.getBoolean("providerConfigured")){"后台尚未配置支付渠道，不能开放线上支付"};require(on!=r.getBoolean("policyOnlinePaymentEnabled")){"策略未变化"};body.put("enabled",on);if(on)"开放新线上支付"else "关闭新线上支付，在途回调、查单、退款和对账继续处理"};"payment-reservation"->{val n=value.toIntOrNull();require(n!=null&&n in 2..30){"待付款库存保留时间须2至30分钟"};require(n!=r.getInt("paymentReservationMinutes")){"时限未变化"};body.put("paymentReservationMinutes",n);"新订单待付款库存保留时间调整为 $n 分钟"};else->error("未知支付策略操作")};val id=UUID.randomUUID().toString();val proof=JSONObject().put("employeeId",actor.employeeId).put("action",action).put("online",r.getBoolean("policyOnlinePaymentEnabled")).put("minutes",r.getInt("paymentReservationMinutes")).put("confirmation",message+"\n基于第${r.getInt("policyVersion")}版策略\n原因：${reason.trim()}");return LiveCommand(id,actor.employeeId,"调整门店支付策略","payment.policy.manage",listOf(LiveStep("$commercePolicyRoot/$action",body.toString(),"idempotency-key","native-business-$id",JSONObject().put("commercePolicy",proof).toString())))}
val LiveStep.commercePolicyProof:JSONObject? get()=recoveryBody?.let{JSONObject(it).optJSONObject("commercePolicy")}
fun validateCommercePolicyReply(text:String,s:LiveStep){val r=JSONObject(text);val d=r.getJSONObject("data");val p=s.commercePolicyProof!!;val b=JSONObject(s.body);val row=d.getJSONObject("row");require(r.getJSONObject("meta").getInt("protocol")==1&&r.getJSONObject("meta").get("replayed") is Boolean&&d.getString("employeeId")==p.getString("employeeId")&&d.getString("requestKey")==s.key&&d.getString("action")==p.getString("action"));require(row.getInt("policyVersion")==b.getInt("expectedVersion")+1&&row.getString("updatedByEmployeeId")==p.getString("employeeId")&&row.getString("reason")==b.getString("reason")&&row.getBoolean("policyOnlinePaymentEnabled")==if(b.has("enabled"))b.getBoolean("enabled")else p.getBoolean("online"));require(row.getInt("paymentReservationMinutes")==if(b.has("paymentReservationMinutes"))b.getInt("paymentReservationMinutes")else p.getInt("minutes"));require(row.getBoolean("onlinePaymentEnabled")==(row.getBoolean("policyOnlinePaymentEnabled")&&row.getBoolean("providerConfigured"))){"支付策略回执状态矛盾"}}
